Hi folks! I'm converting my Pytorch model on C++ via Torchscipt. But when I tested the inference time, it turned out that my C++ model is two times slower than my original Python model.
What could be the reason for this behavior?  Or am I mistaken somewhere?
Ubuntu 16.04, CUDA: 9.1, cuDNN: 7.1.3
Net is a Wide ResNet 50-2.
Converting in Torchscript code:
net = MyNet()
net.load_state_dict('model.pth')
net.train(False)
example = torch.rand(1, 3, 224, 224)

with torch.no_grad():
    traced_script_module = torch.jit.trace(net, example)

traced_script_module.save('model.pt')
Python inference time test code:
net = MyNet()
net.load_state_dict('model.pth')
net.train(False)
net.cuda()

test_number = 1010
batch_num = 8
skip_numbers = 10

batch = torch.randn(batch_num, 3, 224, 224).cuda()

times = 0

for i in range(test_number):
    start = int(round(time.time() * 1000))
    with torch.no_grad():
        _, __ = net(batch)
    torch.cuda.synchronize()
    end = int(round(time.time() * 1000))

    elapsed_mseconds = end - start

    if i > skip_numbers:
        times += elapsed_mseconds

print('Mean time: {} msec'.format(times / (test_number - skip_numbers)))
C++ inference time test code:
#include <torch/torch.h>
#include <torch/script.h>

#include <ATen/ATen.h>

#include <iostream>
#include <memory>
#include <chrono>
#include <ctime>

void time_test(const char* model_name) {
    std::shared_ptr<torch::jit::script::Module> module = torch::jit::load(model_name);
    module->to(at::kCUDA);

    int batch_num = 8;
    int test_number = 1010;
    int skip_numbers = 10;

    std::vector<torch::jit::IValue> batch;
    batch.push_back(torch::randn({batch_num, 3, 224, 224}).to(at::kCUDA));

    std::chrono::time_point<std::chrono::system_clock> start, end;

    int times = 0;

    for (int j = 0; j < test_number; ++j) {
        start = std::chrono::system_clock::now();
        auto output = module->forward(batch);

        // synchronizing
        auto out_elems = output.toTuple()->elements();
        auto embed = out_elems[1].toTensor();
        embed.to(at::kCPU);

        end = std::chrono::system_clock::now();

        long elapsed_mseconds = std::chrono::duration_cast<std::chrono::milliseconds>(end-start).count();

        if (j > skip_numbers) {
            times += elapsed_mseconds;
        }
    }

    std::cout << "Mean time: " << times / (test_number - skip_numbers) << " msec" << '\n';
}

int main(int argc, const char* argv[]) {
    time_test(argv[1]);
}
As a result I got 25 msec for Python and 51 msec for C++.

